def diagnostic_gates(acquisitions):
    """Conditional gates do not count as scheduled lessons unless triggered."""
    phase_ids = defaultdict(list)
    for lesson in acquisitions:
        phase_ids[lesson["phase"]].append(lesson["lesson_id"])
