        ("D05_WORLD_MODEL", "R225", "physical, life, body, geographic, astronomical, and hazard systems", [phase_ids["P5_NATURAL_QUANTITATIVE_WORLD"][0], phase_ids["P5_NATURAL_QUANTITATIVE_WORLD"][-1]]),
