def build_source_accounting(acquisitions):
    v4 = json.loads(V4.read_text(encoding="utf-8"))
    originals = {row["source_id"]: row for row in v4["source_accounting"]}
    expected = [f"C{i:03d}" for i in range(1, 241)]
    if sorted(originals) != expected:
        raise ValueError("v4 provenance inventory is not exactly C001-C240")
    mapped = defaultdict(list)
    for lesson in acquisitions:
        for source in lesson["source_provenance"]:
            if isinstance(source, str) and source.startswith("C") and source[1:].isdigit():
                mapped[source].append(lesson)

    records = []
    for source_id in expected:
        source = originals[source_id]
        target_lessons = mapped[source_id]
        if not target_lessons:
            raise ValueError(f"unaccounted source candidate {source_id}")
        has_standalone = any(
            {
                p
                for p in lesson["source_provenance"]
                if isinstance(p, str) and p.startswith("C") and p[1:].isdigit()
            }
            == {source_id}
            for lesson in target_lessons
        )
        disposition = "active" if has_standalone else "consolidated"
        evidence = [
            {
                "lesson_id": lesson["lesson_id"],
                "topic": lesson["topic"],
                "point": lesson["point"],
                "principal_novelty_type": lesson["principal_novelty"]["type"],
            }
            for lesson in target_lessons
        ]
        lesson_phrase = "; ".join(
            f"{row['lesson_id']} ({row['topic']} — {row['point']})" for row in evidence
        )
        if disposition == "active":
            rationale = (
                f"The candidate topic '{source['original_topic']}' and proposed point "
                f"'{source['original_point']}' have a directly attributable acquisition realization in "
                f"{lesson_phrase}. The candidate supplies provenance, while the v6 lesson's actual frontier, "
                "prerequisites, and world constraints control authoring."
            )
        else:
            rationale = (
                f"No candidate-shaped standalone lesson is preserved. The independently teachable content of "
                f"'{source['original_topic']}' / '{source['original_point']}' is consolidated or decomposed across "
                f"{lesson_phrase}. This avoids treating the candidate's named bundle as proof of one novelty."
            )
        records.append(
            {
                "source_id": source_id,
